add_filter( 'woocommerce_order_actions', 'perfectpixel_resend_email_actions' );
add_action( 'woocommerce_order_action_perfectpixel_resend_processing', 'perfectpixel_resend_processing_email' );
add_action( 'woocommerce_order_action_perfectpixel_resend_completed', 'perfectpixel_resend_completed_email' );
add_action( 'woocommerce_order_action_perfectpixel_resend_on_hold', 'perfectpixel_resend_on_hold_email' );

function perfectpixel_resend_email_actions( $actions ) {
	$actions['perfectpixel_resend_processing'] = 'Επαναποστολή email «Σε επεξεργασία»';
	$actions['perfectpixel_resend_completed']  = 'Επαναποστολή email «Ολοκληρωμένη»';
	$actions['perfectpixel_resend_on_hold']    = 'Επαναποστολή email «Σε αναμονή»';
	return $actions;
}

function perfectpixel_resend_order_email( $order, $email_id, $label ) {
	foreach ( WC()->mailer()->get_emails() as $email ) {
		if ( $email->id === $email_id ) {
			$email->trigger( $order->get_id(), $order );
			$order->add_order_note( sprintf( 'Το email «%s» στάλθηκε ξανά χειροκίνητα.', $label ), false, true );
		}
	}
}

function perfectpixel_resend_processing_email( $order ) {
	perfectpixel_resend_order_email( $order, 'customer_processing_order', 'Σε επεξεργασία' );
}

function perfectpixel_resend_completed_email( $order ) {
	perfectpixel_resend_order_email( $order, 'customer_completed_order', 'Ολοκληρωμένη' );
}

function perfectpixel_resend_on_hold_email( $order ) {
	perfectpixel_resend_order_email( $order, 'customer_on_hold_order', 'Σε αναμονή' );
}
